mapper.select:
SELECT STYLE_ID AS styleId , CMPNY_CD AS cmpnyCd , STYLE_NAME AS styleName , STYLE_TY AS styleTy , USE_FL AS useFl , DATE_FORMAT(IFNULL(UPDATE_DT, CREATION_DT), '%Y-%m-%d') AS modifyDt FROM CM_WIDGET_STYLE WHERE CMPNY_CD = #{cmpnyCd}
AND STYLE_TY = #{styleTy}
AND STYLE_NAME LIKE CONCAT('%', #{styleName}, '%')
ORDER BY STYLE_ID ASC

SELECT CASE WHEN COUNT(*) = 0 THEN 'O' ELSE 'X' END
  FROM CM_WIDGET
 WHERE CMPNY_CD = #{cmpnyCd}
   AND STYLE_ID = #{styleId}

mapper.insert:
