)

mapper.update:
UPDATE CM_WIDGET_STYLE
   SET STYLE_NAME = #{styleName}
     , STYLE_TY = #{styleTy}
     , HTML_TEMPLATE = #{htmlTemplate}
     , CSS_TEMPLATE = #{cssTemplate}
     , JS_TEMPLATE = #{jsTemplate}
     , USE_FL = #{useFl}
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
 WHERE STYLE_ID = #{styleId}
   AND CMPNY_CD = #{cmpnyCd}

mapper.delete:
